1510	/// Check if we're at a block-level construct that can interrupt a paragraph.
1511	///
1512	/// Per CommonMark, these constructs can interrupt paragraphs:
1513	/// - ATX headings (# followed by space or EOL)
1514	/// - Fenced code blocks (``` or ~~~)
1515	/// - Block quotes (>)
1516	/// - Thematic breaks (---, ***, ___)
1517	/// - List items (-, *, +, or ordered markers) - with restrictions
1518	/// - HTML blocks (certain types)
1519	///
1520	/// Note: Setext headings and indented code blocks do NOT interrupt paragraphs.
1521	/// Also, lines with 4+ spaces of indentation cannot start these constructs
1522	/// (they would be indented code blocks instead).
1523	///
1524	/// ## List Interruption Rules (CommonMark §5.2)
1525	///
1526	/// - Bullet lists can interrupt paragraphs if item has content OR marker is followed by blank line
1527	/// - Ordered lists can interrupt paragraphs ONLY if starting with `1` AND not empty
1528	pub(crate) fn at_block_interrupt(p: &mut MarkdownParser) -> bool {
1529	    // Per CommonMark, lines indented 4+ spaces cannot start block constructs
1530	    // that interrupt paragraphs - they would be indented code blocks.
1531	    // Tabs count as 4 spaces per CommonMark §2.2.
1532	    if p.line_start_leading_indent() >= INDENT_CODE_BLOCK_SPACES {
1533	        // Inside list items, allow list markers at the current indent to
1534	        // interrupt paragraphs (nested lists).
1535	        if (p.state().list_nesting_depth > 0 || p.state().list_item_required_indent > 0)
1536	            && (at_bullet_list_item(p) || at_order_list_item(p))
1537	        {
1538	            return true;
1539	        }
1540	        return false;
1541	    }
1542	
1543	    // ATX heading: # at line start (must have space/tab after per CommonMark §4.2)
1544	    // Use checkpoint to look ahead and verify it's a valid heading
1545	    if at_header(p) {
1546	        return is_valid_atx_heading_start(p);
1547	    }
1548	
1549	    // Fenced code block (``` or ~~~) - lexer already ensures line start
1550	    if at_fenced_code_block(p) {
1551	        return true;
1552	    }
1553	
1554	    // Block quote (>)
1555	    if at_quote(p) {
1556	        return true;
1557	    }
