/// Scan the info string of a backtick fence starting at the current token and
/// return the range of the first stray backtick, if any.
///
/// This advances the parser, so it must be called inside a [`MarkdownParser::lookahead`]
/// (or another context that rewinds afterwards).
fn info_string_backtick_range_inner(p: &mut MarkdownParser) -> Option<TextRange> {
    if p.at(TRIPLE_TILDE) {
        return None;
    }

    if p.at(T!["```"]) {
        p.bump(T!["```"]);
    } else if p.at(BACKTICK) {
        p.bump(BACKTICK);
    } else {
        return None;
    }

    while !p.at_inline_end() {
        if p.at(BACKTICK) || p.at(T!["```"]) {
            return Some(p.cur_range());
        }
        p.bump(p.cur());
    }

    None
}

