/// info string contains a backtick character, return the range of the first
/// stray backtick. Otherwise return `None`.
///
/// Per CommonMark §4.5, such a line is not a valid code fence and is parsed as a
/// paragraph. Callers use this to emit a diagnostic before falling back to
/// paragraph parsing. Tilde fences are unaffected (they may contain backticks in
/// their info string).
pub(crate) fn backtick_fence_info_backtick_range(p: &mut MarkdownParser) -> Option<TextRange> {
    p.lookahead(|p| {
        if !p.at_start_of_input() && !is_line_start_within_indent(p, MAX_BLOCK_PREFIX_INDENT) {
            return None;
        }
        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);

        let rest = p.source_after_current();
        let (fence_char, _) = detect_fence(rest)?;
        if fence_char != '`' {
            return None;
        }

        info_string_backtick_range_inner(p)
    })
